 @Override public void onCreate(Bundle state){super.onCreate(state);prefs=getSharedPreferences("telugu_words",MODE_PRIVATE);theme=prefs.getString("theme","system");rate=prefs.getFloat("rate",.95f);engine=new Transliterator(loadWords());try{JSONObject o=new JSONObject(prefs.getString("custom","{}"));Iterator<String>k=o.keys();while(k.hasNext()){String w=k.next();engine.custom.put(w,o.getString(w));}}catch(Exception ignored){}engine.natural=prefs.getBoolean("natural",true);engine.capital=prefs.getBoolean("capital",true);if(state!=null)text=state.getString("text",text);roman=engine.convert(text);audio=(AudioManager)getSystemService(AUDIO_SERVICE);setVolumeControlStream(AudioManager.STREAM_MUSIC);render();initTts(prefs.getString("ttsEngine",null));}
 private Map<String,String>loadWords(){Map<String,String>m=new LinkedHashMap<>();try(BufferedReader r=new BufferedReader(new InputStreamReader(getAssets().open("words.tsv"),StandardCharsets.UTF_8))){String l;while((l=r.readLine())!=null){String[]p=l.split("\t",2);if(p.length==2)m.put(p[0],p[1]);}}catch(Exception e){lastError="Dictionary could not load";}return m;}
 private int dp(float v){return Math.round(getResources().getDisplayMetrics().density*v);}private void colors(){boolean dark=theme.equals("dark")||(theme.equals("system")&&(getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);bg=Color.parseColor(dark?"#171926":"#EEF1FA");card=Color.parseColor(dark?"#272A3A":"#FCFCFF");ink=Color.parseColor(dark?"#E6E6F2":"#24283E");muted=Color.parseColor(dark?"#ADB1C7":"#737C96");purple=Color.parseColor(dark?"#C4AAFF":"#7A55D2");soft=Color.parseColor(dark?"#403550":"#EDE7FA");}
