 private void convertView(){addText(body,"మీ తెలుగు. English అక్షరాలు.",24,purple);addText(body,"మాట మనదే. ఉచ్చారణ తెలుగుదే.",12,muted);LinearLayout p=panel("మీ తెలుగు");source=editor(text,"తెలుగులో రాయండి…",3);source.setImeHintLocales(new android.os.LocaleList(new Locale("te","IN")));p.addView(source);source.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){if(binding)return;stopSpeech();text=s.toString();roman=engine.convert(text);if(output!=null){binding=true;output.setText(roman);binding=false;}}public void afterTextChanged(Editable e){}});paired(p,button("మాట్లాడండి",false,()->dictate()),button("Paste",false,()->{android.content.ClipboardManager cb=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(cb.hasPrimaryClip()&&cb.getPrimaryClip().getItemCount()>0)source.setText(cb.getPrimaryClip().getItemAt(0).coerceToText(this));}),button("Clear",false,()->source.setText("")));
 p=panel("English అక్షరాల్లో");LinearLayout styles=row();Button natural=button("Natural",false,()->setNatural(true)),sound=button("Sound",false,()->setNatural(false));natural.setAlpha(engine.natural?1f:.5f);sound.setAlpha(engine.natural?.5f:1f);styles.addView(natural,new LinearLayout.LayoutParams(0,dp(43),1));styles.addView(sound,new LinearLayout.LayoutParams(0,dp(43),1));p.addView(styles);output=editor(roman,"Mee maata ikkada…",3);output.setTextColor(purple);p.addView(output);output.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int count){if(!binding)roman=s.toString();}public void afterTextChanged(Editable e){}});paired(p,button("Copy",true,()->copy(roman)),button("Share",false,()->share(roman)),button("Save .txt",false,()->export()));fullButton(p,"▶ తెలుగులో వినండి",false,()->{hideKeyboard();current="Listen";render();speak(false);});
 p=panel("Quick phrases");fullButton(p,"ఏమండీ, ఎలా ఉన్నారు?",false,()->{text="ఏమండీ, ఎలా ఉన్నారు? భోజనం తిన్నారా?";roman=engine.convert(text);render();});fullButton(p,"Telugu + English",false,()->{text="రేపు meeting ఉంది. 10:30 కి call చేయండి 😊";roman=engine.convert(text);render();});addText(p,"Text conversion offline. Voice typing / కొన్ని speech voices కి internet అవసరం ఉండవచ్చు.",11,muted);}
